function faviconIcoAd(string $key): void {
    try {
        if (function_exists('db')) {
            $pdo=db(); $stmt=$pdo->prepare('SELECT enabled, ad_code FROM ads_settings WHERE ad_key=? LIMIT 1');
            $stmt->execute([$key]); $row=$stmt->fetch(PDO::FETCH_ASSOC);
            if ($row && (int)$row['enabled']===1 && trim((string)($row['ad_code']??''))!=='') echo $row['ad_code'];
        }
    } catch(Throwable $e) {}
}
