<script>
(()=>{
const $=id=>document.getElementById(id); let image=null,source='image',icoBlob=null;
function hexToRgb(hex){const n=parseInt(hex.slice(1),16);return[(n>>16)&255,(n>>8)&255,n&255]}
function drawCanvas(size){const c=document.createElement('canvas');c.width=c.height=size;const x=c.getContext('2d');const bg=$('bg').value,fg=$('fg').value,p=+ $('padding').value/100,r=+ $('radius').value/100;x.clearRect(0,0,size,size);const rr=size*r/2;x.save();x.beginPath();x.moveTo(rr,0);x.arcTo(size,0,size,size,rr);x.arcTo(size,size,0,size,rr);x.arcTo(0,size,0,0,rr);x.arcTo(0,0,size,0,rr);x.closePath();x.clip();x.fillStyle=bg;x.fillRect(0,0,size,size);const inset=size*p;const w=size-inset*2;
if(source==='image'&&image){const iw=image.naturalWidth||image.width,ih=image.naturalHeight||image.height;const contain=$('fit').value==='contain';let dw=w,dh=w;if(contain){const s=Math.min(w/iw,w/ih);dw=iw*s;dh=ih*s}else{const s=Math.max(w/iw,w/ih);dw=iw*s;dh=ih*s}x.drawImage(image,(size-dw)/2,(size-dh)/2,dw,dh)}else{x.fillStyle=fg;x.textAlign='center';x.textBaseline='middle';const val=source==='emoji'?($('emoji').value||'😊'):($('text').value||'S');x.font=(source==='emoji'?Math.round(w*.78):Math.round(w*.62))+'px Arial, sans-serif';x.fillText(val,size/2,size/2+size*.025)}x.restore();return c}
function refresh(){const c=drawCanvas(256);$('preview').getContext('2d').clearRect(0,0,256,256);$('preview').getContext('2d').drawImage(c,0,0);$('radiusVal').textContent=$('radius').value+'%';$('paddingVal').textContent=$('padding').value+'%'}
function setSource(s){source=s;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.source===s));$('uploadRow').classList.toggle('hidden',s!=='image');$('emojiInput').classList.toggle('hidden',s!=='emoji');$('textInput').classList.toggle('hidden',s!=='text');refresh()}
function blobFromCanvas(c){return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(new Error('PNG failed')),'image/png'))}
async function makeIco(){const sizes=[...document.querySelectorAll('.size:checked')].map(x=>+x.value);if(!sizes.length)throw new Error('Select at least one size.');const pngs=[];for(const s of sizes)pngs.push(await blobFromCanvas(drawCanvas(s)));const bufs=await Promise.all(pngs.map(b=>b.arrayBuffer()));const header=6+16*sizes.length;let total=header+bufs.reduce((n,b)=>n+b.byteLength,0);const out=new Uint8Array(total),dv=new DataView(out.buffer);dv.setUint16(0,0,true);dv.setUint16(2,1,true);dv.setUint16(4,sizes.length,true);let off=header;bufs.forEach((b,i)=>{const s=sizes[i];const w=s===256?0:s;let p=6+i*16;out[p]=w;out[p+1]=w;out[p+2]=0;out[p+3]=0;dv.setUint16(p+4,1,true);dv.setUint16(p+6,32,true);dv.setUint32(p+8,b.byteLength,true);dv.setUint32(p+12,off,true);out.set(new Uint8Array(b),off);off+=b.byteLength});return new Blob([out],{type:'image/x-icon'})}
$('file').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>5*1024*1024){$('fileName').textContent='File is larger than 5 MB.';e.target.value='';return}const u=URL.createObjectURL(f),im=new Image();im.onload=()=>{image=im;URL.revokeObjectURL(u);$('fileName').textContent=f.name;setSource('image')};im.onerror=()=>{URL.revokeObjectURL(u);$('fileName').textContent='Unable to read this image.'};im.src=u});
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>setSource(b.dataset.source)));document.querySelectorAll('input[name=source]').forEach(r=>r.addEventListener('change',()=>setSource(r.value)));['emoji','text','bg','fg','radius','padding','fit'].forEach(id=>$(id).addEventListener('input',refresh));$('fit').addEventListener('change',refresh);
$('generate').addEventListener('click',async()=>{const btn=$('generate');btn.disabled=true;$('status').textContent='Generating favicon.ico...';try{icoBlob=await makeIco();const a=document.createElement('a');a.href=URL.createObjectURL(icoBlob);a.download='favicon.ico';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);$('status').textContent='favicon.ico generated and downloaded successfully.'}catch(e){$('status').textContent=e.message||'Could not generate favicon.ico.'}btn.disabled=false});
$('reset').addEventListener('click',()=>{image=null;$('file').value='';$('fileName').textContent='PNG, JPG, JPEG, WEBP, GIF or SVG · max 5 MB';$('bg').value='#FFFFFF';$('fg').value='#1537D4';$('radius').value=10;$('padding').value=10;$('fit').value='contain';$('emoji').value='🚀';$('text').value='S';document.querySelectorAll('.size').forEach(x=>x.checked=true);setSource('image');$('status').textContent='Ready to generate your ICO file.'});
$('selectAll').addEventListener('click',()=>document.querySelectorAll('.size').forEach(x=>x.checked=true));$('clearAll').addEventListener('click',()=>document.querySelectorAll('.size').forEach(x=>x.checked=false));$('copySnippet').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('snippet').value);$('copySnippet').textContent='Copied!';setTimeout(()=>$('copySnippet').textContent='Copy Code',1200)}catch(e){$('snippet').select();document.execCommand('copy')}});refresh();
})();
</script></body></html>